import{_ as n,c as s,o as e,ag as l}from"./chunks/framework.FgzfQ7Ey.js";const d=JSON.parse('{"title":"作用域与作用域链（Scope & Scope Chain）","description":"","frontmatter":{},"headers":[],"relativePath":"js/scope.md","filePath":"js/scope.md","lastUpdated":1764505738000}'),t={name:"js/scope.md"};function o(i,a,r,p,c,h){return e(),s("div",null,[...a[0]||(a[0]=[l(`<h1 id="作用域与作用域链-scope-scope-chain" tabindex="-1">作用域与作用域链（Scope &amp; Scope Chain） <a class="header-anchor" href="#作用域与作用域链-scope-scope-chain" aria-label="Permalink to &quot;作用域与作用域链（Scope &amp; Scope Chain）&quot;">​</a></h1><h2 id="_1-概念定义" tabindex="-1">1. 概念定义 <a class="header-anchor" href="#_1-概念定义" aria-label="Permalink to &quot;1. 概念定义&quot;">​</a></h2><ul><li><strong>作用域</strong>：在 JavaScript 中，作用域指变量和函数的可访问范围。</li><li><strong>作用域链</strong>：作用域链是一系列作用域的顺序链接，内层作用域可以访问外层作用域的变量。</li></ul><h2 id="_2-产生原因-工作原理" tabindex="-1">2. 产生原因 / 工作原理 <a class="header-anchor" href="#_2-产生原因-工作原理" aria-label="Permalink to &quot;2. 产生原因 / 工作原理&quot;">​</a></h2><ul><li><strong>产生原因</strong>：作用域链确保函数内部可以正确访问外部变量，同时避免变量污染全局命名空间。</li><li><strong>工作原理</strong>：当函数执行时，会创建一个执行上下文（Execution Context）。每个上下文包含自己的变量对象（Variable Object）和指向外部环境的引用。查找变量时，会从当前作用域开始，沿着作用域链向外层查找，直到找到变量或者到达全局作用域。</li></ul><h2 id="_3-典型示例" tabindex="-1">3. 典型示例 <a class="header-anchor" href="#_3-典型示例" aria-label="Permalink to &quot;3. 典型示例&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>function outer() {</span></span>
<span class="line"><span>  const outerVar = &#39;I am outer&#39;;</span></span>
<span class="line"><span>  function inner() {</span></span>
<span class="line"><span>    const innerVar = &#39;I am inner&#39;;</span></span>
<span class="line"><span>    console.log(outerVar);  // 可以访问外层作用域变量</span></span>
<span class="line"><span>  }</span></span>
<span class="line"><span>  inner();</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>outer();</span></span></code></pre></div><ul><li><strong>解释</strong>：在这个示例中，<code>inner</code> 函数可以访问 <code>outerVar</code>，因为它存在于外层函数的作用域中。查找顺序遵循作用域链，从内到外查找变量。</li></ul><h2 id="_4-应用场景" tabindex="-1">4. 应用场景 <a class="header-anchor" href="#_4-应用场景" aria-label="Permalink to &quot;4. 应用场景&quot;">​</a></h2><ul><li><strong>闭包实现</strong>：作用域链是闭包形成的基础。</li><li><strong>模块化代码</strong>：通过函数作用域保护变量，避免全局污染。</li><li><strong>变量访问控制</strong>：管理变量的可访问性，确保内部状态安全。</li></ul><h2 id="_5-常见考点与陷阱" tabindex="-1">5. 常见考点与陷阱 <a class="header-anchor" href="#_5-常见考点与陷阱" aria-label="Permalink to &quot;5. 常见考点与陷阱&quot;">​</a></h2><ul><li><strong>作用域链顺序</strong>：变量查找从内到外，直到全局作用域。</li><li><strong>闭包与作用域链</strong>：闭包可以延长外部作用域变量的生命周期，容易造成内存泄漏。</li><li><strong>变量遮蔽（Shadowing）</strong>：内层变量与外层同名时，会遮蔽外层变量。</li></ul><h2 id="_6-优缺点总结" tabindex="-1">6. 优缺点总结 <a class="header-anchor" href="#_6-优缺点总结" aria-label="Permalink to &quot;6. 优缺点总结&quot;">​</a></h2><ul><li><strong>优点</strong>： <ul><li>保证变量访问的可预测性；</li><li>提供封装和数据保护机制；</li><li>支持闭包和模块化编程。</li></ul></li><li><strong>缺点</strong>： <ul><li>查找变量需要沿作用域链逐级查找，嵌套层数过多时性能下降；</li><li>错误使用闭包容易造成内存泄漏。</li></ul></li></ul><h2 id="_7-一句话总结" tabindex="-1">7. 一句话总结 <a class="header-anchor" href="#_7-一句话总结" aria-label="Permalink to &quot;7. 一句话总结&quot;">​</a></h2><ul><li>作用域链确保变量查找顺序和访问规则，使内层函数能够访问外层函数的变量，实现封装和闭包机制。</li></ul><p>参考： <a href="https://github.com/AttemptWeb/Record/issues/11" target="_blank" rel="noreferrer">图解</a></p>`,17)])])}const g=n(t,[["render",o]]);export{d as __pageData,g as default};
